+static int get_unix_iff_flags(const char *ifname)
+{
+	int sock;
+	struct ifreq ifr;
+	size_t len;
+
+	if (ifname == NULL)
+		return -1;
+
+	len = strlen(ifname);
+	if (len == 0 || len >= IFNAMSIZ)
+		return -1;
+
+	sock = socket(AF_INET, SOCK_DGRAM, 0);
+	if (sock < 0)
+		return -1;
+
+	memset(&ifr, 0, sizeof(ifr));
+	memcpy(ifr.ifr_name, ifname, len);
+
+	if (ioctl(sock, SIOCGIFFLAGS, &ifr) < 0) {
+		close(sock);
+		return -1;
+	}
+
+	close(sock);
+	return ifr.ifr_flags;
+}
+#endif
+
+/*
+ * Returns the sdl_type (IANA ifType) for the given interface name,
+ * or -1 if not found.
+ */
+#if defined(__APPLE__) || defined(__FreeBSD__) || defined(__OpenBSD__)
+static int get_unix_sdl_type(const char *ifname)
+{
+	struct ifaddrs *ifap, *ifa;
+	int type = -1;
+
+	if (ifname == NULL)
+		return -1;
+
+	if (getifaddrs(&ifap) != 0)
+		return -1;
+
+	for (ifa = ifap; ifa != NULL; ifa = ifa->ifa_next) {
+		if (ifa->ifa_addr == NULL)
+			continue;
+		if (ifa->ifa_addr->sa_family != AF_LINK)
+			continue;
+		if (strcmp(ifa->ifa_name, ifname) != 0)
+			continue;
+
+		struct sockaddr_dl *sdl = (struct sockaddr_dl *)ifa->ifa_addr;
+		type = sdl->sdl_type;
+		break;
+	}
+
+	freeifaddrs(ifap);
+	return type;
+}
+#else
+static int get_unix_sdl_type(const char *ifname _U_)
+{
+	return -1;
+}
+#endif
